501	            if (claim.getNumberPeriod() != null) {
502	                claims.retireNumberWithin(sheetId, claim.getNumberPeriod(), claim.getNumberSeq());
503	            }
504	            number(numbering, claim);
505	        }
506	        Claim saved = claims.saveAndFlush(claim);
507	        record("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber(),
508	                " from=" + from.getName() + " to=" + to.getName());
509	        rollup.recordChanges(sheetId, user, before);
