690	     * (its topmost ancestor and every descendant of that), or while the sheet numbers by period, the next
691	     * within the period its due-by falls in (in no period: the next in the sheet's X sequence).
692	     */
693	    private void number(Sheet sheet, Claim claim) {
694	        if (!sheet.numbersByPeriod()) {
695	            int year = fiscalYearOf(sheet, claim.getDueBy() != null ? claim.getDueBy() : claim.getDate());
696	            claim.setFiscalNumber(year, sheets.nextFiscalNumberInTree(sheet.getId(), year));
