717	     * Refuse to open a claim whose due-by falls in a period with a cap when its person already has that
718	     * many OPEN or PENDING claims due inside the period.
719	     */
720	    private void refuseOverCap(String sheetId, Claim claim) {
721	        Period period = periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
722	                .filter(p -> p.contains(claim.getDueBy()))
723	                .findFirst().orElse(null);
724	        if (period == null || period.getCap() == null) return;
725	        long open = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId()).stream()
726	                .filter(c -> !c.getId().equals(claim.getId()))
727	                .filter(c -> c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.PENDING)
728	                .filter(c -> period.contains(c.getDueBy()))
729	                .count();
730	        if (open >= period.getCap()) throw new ClaimCapReachedException();
